  keys(cur.scale, [tClick - f2s(2), tClick, tClick + f2s(4)], [[100, 100], [82, 82], [100, 100]], 50);
  keys(btn.scale, [tClick - f2s(1), tClick + f2s(2), tClick + f2s(6)], [[100, 100], [93, 93], [100, 100]], 50);
