  return [p[0] + (r.left - a[0]) * s[0] / 100, p[1] + (r.top - a[1]) * s[1] / 100, p[0] + (r.left + r.width - a[0]) * s[0] / 100, p[1] + (r.top + r.height - a[1]) * s[1] / 100];
