  var r = shape(c, "Etikett Flaeche " + s), g = grp(r, "Flaeche");
  rectG(g, rc.width + size * 0.9, size * 1.45, 0, 0, size * 0.36); fill(g, bg || INK);
  r.position.setValue([x + rc.left + rc.width / 2, y + rc.top + rc.height / 2]);
