    "var s = value; var n = Math.max(0, Math.floor((time - " + t0 + ") * " + cps + ")); var t = n < s.length ? s.substr(0, n) : s;" +
    " (time < " + (tEnd + 0.4) + " && Math.floor(time * 6) % 2 == 0) ? t + '|' : t;";
