    var h1 = [e[0] - L * (tx * Math.cos(0.5) - ty * Math.sin(0.5)), e[1] - L * (ty * Math.cos(0.5) + tx * Math.sin(0.5))];
    var h2 = [e[0] - L * (tx * Math.cos(-0.5) - ty * Math.sin(-0.5)), e[1] - L * (ty * Math.cos(-0.5) + tx * Math.sin(-0.5))];
    P.push(line2([h1, e, h2]));
